examples:
package main

import (
    "bufio"
    "fmt"
    "os"
)

func main() {
    in := bufio.NewReader(os.Stdin)
    out := bufio.NewWriter(os.Stdout)
    defer out.Flush()
    var n, k int
    if _, err := fmt.Fscan(in, &n, &k); err != nil { return }
    a := []int{}
    for {
        var value int
        if _, err := fmt.Fscan(in, &value); err != nil { break }
        a = append(a, value)
    }
    _ = k
    distance := make([]int, n);
    for fill := range distance { distance[fill] = 1000000000; }
    used := make([]int, n);
    for fill := range used { used[fill] = 0; }
    distance[k] = 0;
    for step := 0; step < n; step++ {
        vertex := -1;
        for i := 0; i < n; i++ {
            if (used[i] == 0) {
                if (vertex == -1 || distance[i] < distance[vertex]) {
                    vertex = i;
                }
            }
        }
        if (vertex == -1 || distance[vertex] == 1000000000) {
            break;
        }
        used[vertex] = 1;
        for next := 0; next < n; next++ {
            weight := a[vertex * n + next];
            if (weight >= 0 && used[next] == 0) {
                distance[next] = min(distance[next], distance[vertex] + weight);
            }
        }
    }
    for i := 0; i < n; i++ {
        value := distance[i];
        if (value == 1000000000) {
            value = -1;
        }
        fmt.Fprintln(out, value);
    }
}

